INSERT INTO canonical_capability (id,name,purpose,effect,authority_requirement,value_at_risk_class,input_schema,output_schema,lifecycle_status) VALUES
('token.market.read','Token market read','Read current token price, market capitalization, volume and related market context from approved providers.','read','none','none','{"type":"object","properties":{"asset":{"type":"string"},"network":{"type":"string"},"address":{"type":"string"}}}','{"type":"object"}','limited-production'),
('token.liquidity.analyze','Token liquidity analysis','Analyze token DEX liquidity, pools, venue distribution and trading activity from approved providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('token.holders.analyze','Token holder analysis','Analyze holder concentration and distribution using approved onchain intelligence providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('token.deployer.analyze','Token deployer analysis','Resolve token creator/deployer evidence and inspect associated public onchain context without asserting identity beyond evidence.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('token.security.assess','Token security assessment','Collect provider-attributed token contract/security signals and explain their implications without declaring a token safe.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('wallet.profile','Wallet profile','Read a wallet profile and current public onchain state from approved providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('wallet.performance.analyze','Wallet performance analysis','Analyze historical wallet trading performance from approved providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('wallet.activity.analyze','Wallet activity analysis','Analyze wallet transactions, flows and public activity from approved providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('smartmoney.flow.read','Smart-money flow read','Read provider-defined smart-money capital flows while preserving provider attribution and cohort definitions.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('smartmoney.accumulation.detect','Smart-money accumulation detection','Derive bounded accumulation/distribution signals from preserved smart-money flow evidence.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('wallet.cluster.analyze','Wallet relationship analysis','Analyze first-degree wallet relationships and holder clusters without asserting common ownership.','read','none','none','{"type":"object"}','{"type":"object"}','tested'),
('token.smartmoney.read','Token smart-money read','Read provider-defined smart-money holdings and activity for a specific token.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('protocol.tvl.read','Protocol TVL read','Read provider-normalized protocol TVL and chain/category distribution.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('protocol.yield.read','Protocol yield read','Read current public DeFi yield-pool observations with protocol, chain, asset and TVL context.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('protocol.metrics.read','Protocol metrics read','Read normalized protocol metadata and public operating metrics from approved providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('stablecoin.supply.read','Stablecoin supply read','Read stablecoin supply and chain distribution observations.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production'),
('stablecoin.market.read','Stablecoin market read','Read stablecoin market and peg context from approved providers.','read','none','none','{"type":"object"}','{"type":"object"}','limited-production')
