CREATE TABLE IF NOT EXISTS intelligence_evidence (
  id text PRIMARY KEY,
  owner_user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  job_id text NOT NULL REFERENCES job(id) ON DELETE CASCADE,
  task_id text NOT NULL REFERENCES intelligence_task(id) ON DELETE CASCADE,
  capability_id text NOT NULL REFERENCES canonical_capability(id) ON DELETE RESTRICT,
  implementation_id text NOT NULL,
  provider text NOT NULL,
  subject_kind text NOT NULL CHECK (subject_kind IN ('token','wallet','protocol','stablecoin')),
  subject_query text NOT NULL,
  network text,
  address text,
  status text NOT NULL CHECK (status IN ('verified','partial','unavailable','error')),
  summary text NOT NULL,
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  source_url text,
  observed_at timestamptz NOT NULL,
  fetched_at timestamptz NOT NULL DEFAULT now(),
  freshness_seconds integer,
  provider_confidence numeric,
  derivation_version text,
  limitations jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS intelligence_evidence_owner_job_idx ON intelligence_evidence(owner_user_id,job_id,fetched_at DESC);
CREATE INDEX IF NOT EXISTS intelligence_evidence_capability_idx ON intelligence_evidence(capability_id,provider,fetched_at DESC);
CREATE INDEX IF NOT EXISTS intelligence_evidence_subject_idx ON intelligence_evidence(subject_kind,network,address,fetched_at DESC);

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,purpose=EXCLUDED.purpose,effect=EXCLUDED.effect,authority_requirement=EXCLUDED.authority_requirement,value_at_risk_class=EXCLUDED.value_at_risk_class,input_schema=EXCLUDED.input_schema,output_schema=EXCLUDED.output_schema,lifecycle_status=EXCLUDED.lifecycle_status,updated_at=now();

ON CONFLICT (id) DO UPDATE SET version=EXCLUDED.version,supported_networks=EXCLUDED.supported_networks,pricing=EXCLUDED.pricing,trust_status=EXCLUDED.trust_status,health_status=EXCLUDED.health_status,invocation_kind=EXCLUDED.invocation_kind,known_failure_states=EXCLUDED.known_failure_states,priority=EXCLUDED.priority,enabled=EXCLUDED.enabled,environment_eligibility=EXCLUDED.environment_eligibility,updated_at=now();

ON CONFLICT(worker_version_id,canonical_capability_id) DO UPDATE SET suitability=EXCLUDED.suitability,updated_at=now();

UPDATE worker_version SET capability_requirements='["token.market.read","token.liquidity.analyze","token.holders.analyze","token.deployer.analyze","token.security.assess","smartmoney.flow.read","token.smartmoney.read"]'::jsonb WHERE id='wv-memescout-1';
UPDATE job_contract SET default_capability_requirements='["token.market.read","token.liquidity.analyze","token.holders.analyze","token.deployer.analyze","token.security.assess","smartmoney.flow.read","token.smartmoney.read"]'::jsonb WHERE worker_version_id='wv-memescout-1';
UPDATE worker_version SET capability_requirements='["wallet.profile","wallet.performance.analyze","wallet.activity.analyze","smartmoney.flow.read","smartmoney.accumulation.detect","token.smartmoney.read","wallet.cluster.analyze"]'::jsonb WHERE id='wv-smartmoney-1';
UPDATE job_contract SET default_capability_requirements='["wallet.profile","wallet.performance.analyze","wallet.activity.analyze","smartmoney.flow.read","smartmoney.accumulation.detect","token.smartmoney.read","wallet.cluster.analyze"]'::jsonb WHERE worker_version_id='wv-smartmoney-1';
